import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { roundCents } from './money.js';

/**
 * Invoices overdue as of a date: status 'issued' or 'partially_paid' and dueDate before asOf.
 * @param {Array} invoices
 * @param {string} asOf - YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((inv) => {
      const validStatus = inv.status === 'issued' || inv.status === 'partially_paid';
      const overdue = inv.dueDate < asOf;
      return validStatus && overdue;
    })
    .map((inv) => {
      const daysOverdue = daysBetween(inv.dueDate, asOf);
      const due = balanceDue(inv);
      return {
        number: inv.number,
        customerId: inv.customerId,
        dueDate: inv.dueDate,
        daysOverdue,
        due,
      };
    })
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * VAT summary for invoices: one entry per VAT rate with base and VAT amounts.
 * @param {Array} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const summary = {};

  const validStatuses = new Set(['issued', 'partially_paid', 'paid']);
  const filtered = invoices.filter((inv) => validStatuses.has(inv.status));

  for (const inv of filtered) {
    for (const line of inv.lines) {
      const lineSubtotal = line.qty * line.unitPrice;
      const lineDiscount = lineSubtotal * (line.discountPercent ?? 0) / 100;
      const lineBase = lineSubtotal - lineDiscount;
      const lineVat = roundCents(lineBase * (line.vatRate ?? 0) / 100);

      const rate = line.vatRate ?? 0;
      if (!summary[rate]) {
        summary[rate] = { rate, base: 0, vat: 0 };
      }
      summary[rate].base += lineBase;
      summary[rate].vat += lineVat;
    }
  }

  return Object.values(summary).sort((a, b) => b.rate - a.rate);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty array when no invoices', () => {
  const result = overdueInvoices([], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no overdue invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices finds single overdue invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[0].customerId, 'C-001');
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result[0].daysOverdue, 16);
  assert.equal(result[0].dueDate, '2026-09-21');
});

test('overdueInvoices includes due amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result[0].due, totals.total);
});

test('overdueInvoices excludes draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const result = overdueInvoices([r.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-08' });
  const result = overdueInvoices([paid.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes issued invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result.length, 1);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const withPayment = recordPayment(issued.value, { amount: 5000, date: '2026-10-08' });
  const result = overdueInvoices([withPayment.value], '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, totals.total - 5000);
});

test('overdueInvoices excludes invoices with dueDate equal to asOf', () => {
